import {allowedInterfaceProfiles} from './interface-policy.js';
import {linkExplanation} from './link-explain.js';
import {LAG_MODES} from './lag.js';
import {PROFILES,MEDIA,parseVlans,getProfile,PASSIVE,TRANSPARENT} from './physical.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const input=(label,key,value)=>`<label>${label}<input data-key="${key}" value="${esc(value)}"></label>`;
export function physicalHTML(n,p){return (PASSIVE.includes(n.type)||TRANSPARENT.includes(n.type)?'':`<label>Группа LAG / bond (пусто — самостоятельный порт)<input data-key="lagGroup" maxlength="32" value="${esc(p.lagGroup||'')}"></label>${p.lagGroup?'<label>Режим агрегации<select data-key="lagMode">'+Object.entries(LAG_MODES).map(([k,v])=>'<option value="'+k+'" '+((p.lagMode||'active')===k?'selected':'')+'>'+esc(v)+'</option>').join('')+'</select></label>':''}`)+ `<label>Разъём / установленный модуль<select data-key="profile">${Object.entries(PROFILES).filter(([k])=>!PASSIVE.includes(n.type)||(n.type==='patch_panel'?k==='passive_rj45':['passive_smf','passive_mmf'].includes(k))).map(([k,v])=>`<option value="${k}" ${allowedInterfaceProfiles(n,p).includes(k)?'':'disabled'} ${getProfile(p)===v?'selected':''}>${esc(v.name)}</option>`).join('')}</select></label>${['switch','bridge'].includes(n.type)?`<label>Режим switchport<select data-key="switchMode"><option value="access" ${p.switchMode!=='trunk'?'selected':''}>Access · один VLAN без тега</option><option value="trunk" ${p.switchMode==='trunk'?'selected':''}>Trunk · 802.1Q</option></select></label>${p.switchMode==='trunk'?input('Allowed VLAN (через запятую)','allowedVlans',(p.allowedVlans||[1,10,20]).join(','))+input('Native VLAN (без тега)','nativeVlan',p.nativeVlan||1):input('Access VLAN','accessVlan',p.accessVlan||1)}`:`<label>Кадры интерфейса<select data-key="tagged"><option value="false" ${!p.tagged?'selected':''}>Без тега (обычный NIC)</option><option value="true" ${p.tagged?'selected':''}>802.1Q · VLAN-интерфейс</option></select></label>${p.tagged?input('VLAN ID','accessVlan',p.accessVlan||1):''}`}`}
export function physicalValue(key,value){if(key==='lagGroup'){if(value.length>32)throw Error('Имя LAG до 32 символов');return value.trim()}if(key==='allowedVlans')return parseVlans(value);if(['accessVlan','nativeVlan'].includes(key)){const v=Number(value);if(!Number.isInteger(v)||v<1||v>4094)throw Error('VLAN должен быть от 1 до 4094');return v}if(key==='tagged')return value==='true';return value}
export function cableHTML(l){return `<div class="hint">${esc(linkExplanation(l))}</div><div class="section">СРЕДА И КАБЕЛЬ</div><label>Тип подключения<select data-link-key="medium">${Object.entries(MEDIA).map(([k,v])=>`<option value="${k}" ${l.medium===k||!l.medium&&k==='model'?'selected':''}>${esc(v)}</option>`).join('')}</select></label><label>Длина, м<input data-link-key="length" type="number" min="0" value="${l.length??3}"></label><p>Несовместимая среда, скорость, дальность или пара SFP выключают связность. Пустой слот не передаёт трафик.</p>`}
